from addlib import *
def box(inner,style=''): return f'<div style="background:var(--surface);border-radius:var(--r-md);padding:var(--sp-3) var(--sp-4);{style}">{inner}</div>'
# --- A19 series title separator ---
SEP=[['Due punti + spazio (scelto)','Loki: Stagione 1','Come i titoli con sottotitolo (“Captain America: The First Avenger”); nessun trattino'],['Punto mediano','Loki · Stagione 1','Già usato per i metadati: confonde titolo e dati'],['Parentesi','Loki (Stagione 1)','Allunga il titolo; la riga ha già altre parentesi'],['Virgola','Loki, Stagione 1','Ambigua con “Film, 2008” dei metadati']]
add('Planner',
 block('Titoli di serie: sostituire il trattino lungo',DECI,'Il trattino lungo (—) in “Loki — Stagione 1” è un segno tipico di testo scritto da un\'IA. Nel catalogo ci sono 14 titoli di serie con questa forma (<code>catalog.ts</code>, es. r.69, r.71, r.80, r.90-93). <b>Decisione:</b> due punti seguiti da uno spazio: <b>“Loki: Stagione 1”</b>. Regola per tutte le serie, nelle 5 lingue: <i>Nome della serie</i> + <code>: </code> + <i>etichetta della stagione</i>; in francese uno spazio non separabile prima dei due punti (“Loki : Saison 1”) per la tipografia francese; il titolo originale non si traduce. Gli intervalli di date restano con trattino medio e spazi (“2008 – 2012”). <b>Attenzione:</b> l\'id di ogni titolo è <code>i-${toSlug(name)}</code> (catalog.ts r.14) e finisce nei progressi salvati: la funzione <code>toSlug</code> sta in <code>shared/slug.ts</code>, non incluso nell\'importazione (non verificato). Prima di cambiare i nomi serve un test che confermi che l\'id resta identico, oppure l\'id va scritto esplicito per quei 14 titoli. L\'etichetta “Stagione” è oggi solo in italiano dentro il nome: tradurla è una scelta a parte.',
  tbl(['Separatore','Esempio','Perché'],SEP)+
  tbl(['Lingua','Titolo di serie con stagione (regola)'],[['it','Loki: Stagione 1'],['en','Loki: Season 1'],['fr','Loki : Saison 1 (spazio non separabile prima dei due punti)'],['es','Loki: Temporada 1'],['de','Loki: Staffel 1']])
  +pd([['Separatore nei titoli di serie','trattino lungo “ — ”','due punti + spazio (14 titoli)','catalog.ts r.70-91'],['Id dei titoli','<code>i-${toSlug(name)}</code>','invariato: test obbligatorio','catalog.ts r.14; shared/slug.ts (non verificato)'],['Intervalli di date','trattino medio','invariato','catalog.phases (phase__years)']])),
)
# ---- B12 NextToWatch ----
def ntw(state):
    p={'load':'<div style="width:6rem;aspect-ratio:2/3"><div class="poster-image"><span class="poster-image__state poster-image__state--loading" aria-hidden="true">'+icon('loader')+'</span></div></div>',
       'err':f'<div style="width:6rem;aspect-ratio:2/3"><div class="poster-image"><span class="poster-image__state" role="img" aria-label="{L("poster.missing")}">{icon("image-off")}</span></div></div>'}[state]
    return box(f'<div style="display:flex;gap:var(--sp-4)">{p}<div><div class="dc-fl">{L("planner.next.heading")}</div><strong>{L("planner.types.film")}</strong><p style="margin:0">{L("planner.next.markWatched")}</p></div></div>')
add('Planner',
 block('Decisione · “Prossimo da guardare” in caricamento',DECI,'Oggi, mentre i dati del titolo arrivano, la scheda scompare e poi riappare. <b>Decisione:</b> la scheda <b>non si smonta mai</b>: titolo, tipo e azione vengono dal catalogo (disponibili subito); solo la locandina è asincrona. Stato dell\'immagine: riquadro 2:3 con fondo piatto <code>--poster-bg</code> da subito, spinner dopo <code>--delay-pending</code>, dissolvenza <code>--dur-ui</code> a caricamento riuscito, e in errore l\'icona <code>image-off</code>. Quando il prossimo titolo cambia (dopo una spunta) la locandina precedente resta finché la nuova non è pronta: nessun vuoto. Le dimensioni del riquadro non cambiano in nessuno stato.',
  '<div class="dc-row">'+fr('light','360px',ntw('load'),'Immagine in caricamento')+fr('dark','360px',ntw('err'),'Immagine non disponibile · scuro')+'</div>'
  +pd([['Caricamento','la scheda sparisce e riappare','scheda fissa; solo la locandina cambia stato','NextToWatch.tsx; PosterImage.less r.57-69'],['Cambio del prossimo titolo','vuoto, poi nuova immagine','locandina vecchia fino al caricamento della nuova','NextToWatch.tsx']])),
)
# ---- B13 share box layout ----
def sch(order):
    items={'p':box('<strong>I tuoi progressi</strong><br>…',''),'n':box('<strong>Prossimo da guardare</strong><br>…',''),'s':box('<strong>Condividi il tuo planner</strong>','background:var(--highlight);color:var(--ink-static);text-align:center')}
    return order
G_BEFORE='<div style="display:grid;grid-template-columns:1.3fr 1fr;gap:var(--sp-3);align-items:start"><div style="display:grid;gap:var(--sp-3)">'+box('<strong>I tuoi progressi</strong>','min-height:9rem')+'</div>'+box('<strong>Prossimo da guardare</strong>','min-height:9rem')+'</div>'+box('<strong>Condividi il tuo planner</strong>','background:var(--highlight);color:var(--ink-static);margin-top:var(--sp-3)')
G_AFTER='<div style="display:grid;grid-template-columns:1.3fr 1fr;gap:var(--sp-3);align-items:stretch"><div style="display:flex;flex-direction:column;gap:var(--sp-3);'+'background:var(--surface);border-radius:var(--r-md);padding:var(--sp-3) var(--sp-4)">'+'<strong>I tuoi progressi</strong><div style="flex:1;min-height:6rem"></div>'+box('<strong>Condividi il tuo planner</strong>','background:var(--highlight);color:var(--ink-static)')+'</div>'+box('<strong>Prossimo da guardare</strong>','min-height:9rem')+'</div>'
add('Planner',
 block('Decisione · “Condividi il tuo planner” a 1098×911',DECI,'A 1098 px di larghezza (tra il tablet, da 40em, e il desktop, da 64em ≈ 1024 px) il riquadro “Condividi il tuo planner” (<code>.progress-card__share</code>) finisce sotto tutto, staccato dalla scheda dei progressi. <b>Decisione:</b> il pulsante è <b>sempre l\'ultima riga dentro la scheda dei progressi</b> (<code>margin-top: auto</code>), a qualsiasi larghezza; nel layout a due colonne le due schede hanno la stessa altezza (<code>align-items: stretch</code>) così il pulsante sta in fondo alla scheda e non sotto la griglia. Sotto 40em la scheda è a larghezza piena e il pulsante resta nella scheda (come oggi). Nessun valore nuovo: usa la griglia <code>Planner.less</code> r.16-18.',
  '<div class="dc-row">'+fr('light','100%',G_BEFORE,'Prima · 1098 px (schema)')+fr('light','100%',G_AFTER,'Dopo · 1098 px (schema)')+'</div>'
  +pd([['Posizione del pulsante di condivisione','in basso, fuori dalla scheda dei progressi','ultima riga nella scheda, <code>margin-top: auto</code>','PlannerSummary.less r.48-70; Planner.less r.15-17'],['Altezza delle due schede','<code>align-items: start</code> (non verificato)','<code>align-items: stretch</code> da 40em','Planner.less r.15-17']])),
)
# ---- B17 mobile bottom padding ----
add('Planner',
 block('Decisione · fondo del planner su mobile',DECI,'Oggi <code>.planner</code> riserva in fondo <code>padding-bottom: var(--floating-progress-clearance)</code> (Planner.less r.7?) per la barra di avanzamento fissa; quando il footer entra in vista la barra sparisce e resta uno spazio vuoto sopra il footer. <b>Regola:</b> la barra non è più una barra fissa che richiede spazio riservato, ma <code>position: sticky; bottom: var(--floating-progress-gap)</code> come ultimo figlio della sezione del planner: segue lo scorrimento e <b>si ferma da sola alla fine della sezione</b>, prima del footer. Nessun <code>padding-bottom</code> di riserva (torna a 0). <code>scroll-padding-bottom: var(--floating-progress-clearance)</code> (base.less r.71) resta, perché il focus non deve finire sotto la barra. I toast continuano a salire sopra la barra (Toast.less r.3-17).',
  tbl(['Aspetto','Prima','Dopo'],[['Barra di avanzamento','fissa, nascosta quando entra il footer','sticky in fondo alla sezione: si ferma prima del footer'],['Spazio sotto la lista','<code>--floating-progress-clearance</code> sempre','0'],['Focus non oscurato','<code>scroll-padding-bottom</code>','invariato'],['Toast','sopra la barra','invariato']])
  +pd([['Spazio in fondo','<code>padding-bottom: var(--floating-progress-clearance)</code>','0; barra sticky','Planner.less r.7?; FloatingProgress.less r.5-15'],['Nascondere la barra vicino al footer','logica di visibilità (<code>data-visible</code>)','non serve più (la barra termina con la sezione)','FloatingProgress.tsx r.22']])),
)
# ---- B27 watched indicator ----
def rowbox(checked,name):
    return f'<label class="title-row__check"><input type="checkbox"{" checked=\"checked\"" if checked else ""} aria-label="{name}"><span class="title-row__box" aria-hidden="true">{icon("check")}</span></label>'
add('Planner',
 block('Decisione · indicatore dei titoli visti su mobile',DECI,'Nel codice la casella (<code>.title-row__box</code>, TitleItem.less r.209-255) ha un bordo <code>--ink</code> di 3px da non spuntata e riempimento <code>--accent</code> da spuntata: non coincide con lo sfondo. L\'indicatore mobile in cui il titolo non visto ha il colore dello sfondo non è stato individuato nel codice (non verificato): questa regola vale per ogni indicatore dello stato visto. <b>Colori decisi:</b> <b>non visto</b> = contorno 3px <code>--ink</code> su riempimento trasparente (visibile su <code>--bg</code> e <code>--surface</code>); <b>visto</b> = riempimento <code>--primary</code> (rosso in chiaro, oro in scuro) con spunta <code>--on-primary</code>; hover (puntatore fine) = contorno <code>--primary</code>. Mai riempire il non visto con <code>--bg</code> o <code>--surface</code>. <b>Struttura:</b> è una colonna a sé a sinistra della scheda, allineata alla riga di sintesi: <b>non</b> è il corpo dell\'accordion, quindi l\'apertura non la allunga. <b>Tablet piccolo:</b> aprire l\'accordion <b>non</b> allunga “Prossimo da guardare”: la griglia lista/colonna usa già <code>align-items: start</code> (Planner.less r.24) e resta così; su desktop la colonna è sticky (r.44).',
  both('320px','<ul style="list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:var(--sp-2)">'+f'<li style="display:flex;align-items:center;gap:var(--sp-3)">{rowbox(False,"non visto")}<span>Non visto</span></li><li style="display:flex;align-items:center;gap:var(--sp-3)">{rowbox(True,"visto")}<span>Visto</span></li></ul>','Non visto · visto')
  +pd([['Non visto','contorno <code>--ink</code> (casella); mobile: non verificato','contorno <code>--ink</code>, mai fondo','TitleItem.less r.209-225'],['Visto','<code>--accent</code> in entrambi i temi','<code>--primary</code> + <code>--on-primary</code> (oro in scuro)','TitleItem.less r.234-241; tokens.less r.36, r.40, r.75, r.79'],['Hover','bordo <code>--accent</code>','<code>--primary</code>','TitleItem.less r.311-317'],['Estensione dell\'accordion','—','colonna a sé: non cresce con il corpo','TitleItem.tsx'],['Prossimo da guardare in tablet piccolo','—','non si allunga','Planner.less r.24, r.43']])),
)
# ---- B29 filter flicker ----
add('Planner',
 block('Decisione · cambio filtro senza sfarfallio',DECI,'<b>Stato su main c520ab1: in parte implementata.</b> Fatto: la dissolvenza parte da 0,85 (<code>@keyframes list-swap-in</code>, motion.less r.812-816) e <code>needle</code> non è più nella chiave: <code>listKey = ordine + JSON dei filtri</code> (Planner.tsx r.144?). <b>Resta da fare:</b> l\'altezza minima precedente durante lo scambio (nessuna regola <code>min-height</code> in Planner.less). Testo della decisione originale: il codice aveva già una transizione: quando cambia la chiave della lista (<code>listKey = ordine + filtri + testo di ricerca</code>, Planner.tsx r.168-176) la lista riceve <code>.planner__list--swap</code>, una dissolvenza da opacità 0,6 a 1 in <code>--dur-hover</code> (120 ms) “così la pagina non lampeggia mai vuota” (motion.less r.244-249, keyframes r.764-768). Il lampo residuo ha due cause leggibili: (a) la partenza a 0,6 si nota come lampo, soprattutto in chiaro; (b) <code>needle</code> (il testo di ricerca) è nella chiave: <b>a ogni lettera</b> digitata la dissolvenza riparte; in più l\'altezza della lista cambia di colpo. <b>Regola:</b> (1) la dissolvenza parte da <b>0,85</b>, non da 0,6; (2) <code>needle</code> esce da <code>listKey</code> (o è ritardato di 150 ms): la ricerca filtra senza ripetere la dissolvenza a ogni lettera; (3) l\'altezza minima della lista resta quella precedente finché il nuovo insieme è disegnato (<code>min-height</code> impostata e tolta in un frame); (4) fasi e righe mantengono la chiave <code>id</code> e non si rimontano; (5) lo stato “nessun risultato” (<code>FiltersEmpty</code>) compare senza passare dal vuoto; (6) con movimento ridotto la transizione resta di sola opacità a 80 ms (già così: <code>--dur-hover</code> vale 80 ms); (7) lo scorrimento è mantenuto.',
  tbl(['Passo','Prima (2b5e07a)','Dopo (main c520ab1)','Stato'],[['Partenza della dissolvenza','opacità 0,6','opacità 0,85','fatto'],['Durata','<code>--dur-hover</code> 120 ms','invariata','—'],['Ricerca','<code>needle</code> dentro <code>listKey</code>: riparte a ogni lettera','fuori da <code>listKey</code>','fatto'],['Altezza','cambia di colpo','altezza minima precedente fino al disegno','da fare'],['Movimento ridotto','80 ms','invariato','—']])
  +pd([['Dissolvenza della lista','da 0,6','da 0,85 (fatto)','motion.less r.812-816'],['Chiave della lista','ordine + filtri + ricerca','ordine + filtri (fatto)','Planner.tsx r.144?'],['Altezza durante lo scambio','nessuna regola','<code>min-height</code> precedente','Planner.tsx r.168-176; Planner.less']])),
)
# ---- B35 saga header ----
def sagahead(align):
    return (f'<div style="display:flex;justify-content:space-between;gap:var(--sp-3);align-items:{align};padding:var(--sp-3) var(--sp-4);background:var(--surface);border-radius:var(--r-md);width:100%;box-sizing:border-box"><h2 class="phase__name" style="margin:0;font-size:var(--fs-h2)">{L("catalog.sagas.infinity")}</h2><span class="phase__count" style="font-weight:600;white-space:nowrap">{L("common.ofCount",done=12,total=30)}</span></div>')
add('Planner',
 block('Decisione · “Saga dell\'Infinito” e conteggio su mobile',DECI,'Il titolo della saga (<code>catalog.sagas.infinity</code>, maiuscolo su due righe) e il conteggio a destra sono centrati in verticale: il conteggio “galleggia” a metà del titolo. <b>Decisione:</b> allineati <b>in basso</b>: <code>align-items: flex-end</code> sulla riga (o <code>last baseline</code> dove supportato), così il conteggio condivide la riga di base dell\'ultima riga del titolo. Vale su mobile; da tablet il titolo sta su una riga e non cambia nulla.',
  '<div class="dc-row">'+phone(f'<div style="padding:var(--sp-3);background:var(--bg);color:var(--ink)">{sagahead("center")}</div>','light',100,320,'Prima · al centro')+phone(f'<div style="padding:var(--sp-3);background:var(--bg);color:var(--ink)">{sagahead("flex-end")}</div>','light',100,320,'Dopo · in basso')+'</div>'
  +pd([['Allineamento titolo saga / conteggio','<code>align-items: center</code> (non verificato)','<code>align-items: flex-end</code>','SagaSection.less (.saga__summary)']])),
)
